import { experiment } from '@caemble/core'
import {
  Baffle,
  Detector,
  FoldingMirror,
  HazeVolume,
  Lens,
  SourceMarker,
  Solid,
} from './geometry'
import {
  Air,
  BlackBaffle,
  LensGlass,
  MirrorSubstrate,
  ScatteringHaze,
  ThinFilm,
  Steel,
} from './material'

export default experiment({
  lengthUnit: 'mm',
  varsSchema: {},
  geometry: () => (
    <>
      <Solid
        id="body"
        size={[60, 8, 8]}
        position={[0, 0, -20]}
        materials={{ body: Steel() }}
      />
      <SourceMarker
        id="source"
        position={[-55, 0, 0]}
        materials={{ body: Air }}
      />
      <Lens id="lens" position={[-30, 0, 0]} materials={{ body: LensGlass }} />
      <FoldingMirror
        id="folding-mirror"
        position={[0, 0, 0]}
        rotation={[0, 0, -Math.PI / 4]}
        materials={{ substrate: MirrorSubstrate, film: ThinFilm }}
      />
      <Baffle
        id="baffle-left"
        position={[-9, 20, 0]}
        size={[3, 3, 28]}
        materials={{ body: BlackBaffle }}
      />
      <Baffle
        id="baffle-right"
        position={[9, 20, 0]}
        size={[3, 3, 28]}
        materials={{ body: BlackBaffle }}
      />
      <HazeVolume
        id="haze"
        position={[0, 27, 0]}
        materials={{ body: ScatteringHaze }}
      />
      <Detector id="detector" position={[0, 44, 0]} materials={{ body: Air }} />
    </>
  ),
  geometryGroup: {
    body: ['body'],
    rayDomain: [
      'lens',
      'folding-mirror',
      'baffle-left',
      'baffle-right',
      'haze',
      'detector',
    ],
    lightSource: ['source'],
    haze: ['haze'],
  },
  surfaceGroup: {
    fixed: ['body.shape/surface/0'],
    loaded: ['body.shape/surface/1'],
    abgBaffle: ['baffle-left.body/surface/1'],
    lambertianBaffle: ['baffle-right.body/surface/0'],
    detector: ['detector.body/surface/2'],
  },
  recordedData: {
    displacement: { task: 'solid', output: 'displacement' },
    stress: { task: 'solid', output: 'stressField' },
    reaction: { task: 'solid', output: 'reaction' },
    secondaryFluenceRate: { task: 'secondary', output: 'fluenceRate' },
    secondaryRadiantFluxDensity: {
      task: 'secondary',
      output: 'radiantFluxDensity',
    },
    traceFluenceRate: { task: 'trace', output: 'fluenceRate' },
    traceRadiantFluxDensity: { task: 'trace', output: 'radiantFluxDensity' },
  },
})

