import { Material } from '@caemble/core'

const opticalMaterial = (
  name: string,
  refractiveIndex: number,
  extinctionCoefficient: number,
  absorptionCoefficient: number,
  scatteringCoefficient: number,
  color: string,
) =>
  new Material(name, {
    color,
    models: {
      optical: {
        model: 'optics.constant-complex-index@1',
        parameters: {
          n: { dtype: 'float64', value: refractiveIndex, unit: '{fraction}' },
          k: { dtype: 'float64', value: extinctionCoefficient, unit: '1' },
        },
      },
      absorption: {
        model: 'optics.constant-absorption@1',
        parameters: {
          alpha: {
            dtype: 'float64',
            value: absorptionCoefficient,
            unit: 'm-1',
          },
        },
      },
      scattering: {
        model: 'optics.constant-scattering@1',
        parameters: {
          sigma: {
            dtype: 'float64',
            value: scatteringCoefficient,
            unit: 'm-1',
          },
        },
      },
    },
  })

export const Air = opticalMaterial('Optical Air', 1, 0, 0, 0, '#dbeafe')
export const LensGlass = opticalMaterial(
  'Lens Glass',
  1.52,
  0,
  0.02,
  0,
  '#60a5fa',
)
export const MirrorSubstrate = opticalMaterial(
  'Mirror Substrate',
  0.2,
  3.2,
  7.3e7,
  0,
  '#94a3b8',
)
export const ThinFilm = opticalMaterial(
  'Five Micrometer Film',
  1.38,
  0,
  0,
  0,
  '#c4b5fd',
)
export const BlackBaffle = opticalMaterial(
  'Black Baffle',
  1.6,
  0.7,
  2000,
  0,
  '#111827',
)
export const ScatteringHaze = opticalMaterial(
  'Scattering Haze',
  1.0003,
  0,
  0.1,
  25,
  '#e0f2fe',
)

// E: 늘어나기 어려운 정도(Pa), nu: 옆으로 수축하는 비율, density: 단위 체적의 질량.
export const Steel = () => new Material('Steel', {
  color: '#7589a0',
  models: { solid: { model: 'mechanics.isotropic-elastic@1', parameters: {
    E: { dtype: 'float64', value: 210e9, unit: 'Pa' },
    nu: { dtype: 'float64', value: 0.3, unit: '1' },
    density: { dtype: 'float64', value: 7850, unit: 'kg.m-3' },
  } } },
})

