import { Box, defineTask } from '@caemble/core'
import { SourceMarker } from '../geometry'
import { Air } from '../material'

const wavelength = (value: number) => ({
  dtype: 'float64' as const,
  value,
  unit: 'nm',
  quantityKind: 'Wavelength' as const,
})

const flux = (value: number) => ({
  dtype: 'float64' as const,
  value,
  unit: 'W',
  quantityKind: 'optics.RadiantFlux' as const,
})

const stokes = (value: readonly [number, number, number, number]) => ({
  dtype: 'float64' as const,
  axes: [{ length: 4 }],
  value,
  unit: '1',
  quantityKind: 'Dimensionless' as const,
})

const direction = {
  dtype: 'float64' as const,
  axes: [{ length: 3 }],
  value: [1, 0, 0],
  unit: '1',
  quantityKind: 'Dimensionless' as const,
}

export default defineTask({
  kernel: { name: 'ray-tracing', version: '2.0.0' },
  lengthUnit: 'mm',
  geometry: () => (
    <>
      <SourceMarker
        id="task-marker"
        position={[0, -80, 0]}
        materials={{ body: Air }}
      />
      <Box
        id="output-grid"
        position={[-12.5, 15.42539667220305, 0]}
        size={[55.05499999999999, 59.20835586224949, 34.044009949093756]}
      />
    </>
  ),
  config: () => ({
    parameters: {
      seed: 20260911,
      maxInteractions: 16,
      minPowerFraction: {
        dtype: 'float64',
        value: 1e-7,
        unit: '{fraction}',
        quantityKind: 'DimensionlessRatio',
      },
      maxPaths: 1024,
    },
    initializations: [
      {
        target: ['experiment.geometry.rayDomain'],
        methodId: 'ray.domain',
        parameters: {},
      },
      {
        target: ['experiment.geometry.lightSource'],
        methodId: 'ray.point-source',
        parameters: {
          wavelength: wavelength(532),
          radiantFlux: flux(0.7),
          rayCount: 256,
          stokes: stokes([1, 1, 0, 0]),
          direction,
          coneHalfAngle: {
            dtype: 'float64',
            value: 2.5,
            unit: 'deg',
            quantityKind: 'PlaneAngle',
          },
        },
      },
      {
        target: ['experiment.geometry.lightSource'],
        methodId: 'ray.point-source',
        parameters: {
          wavelength: wavelength(650),
          radiantFlux: flux(0.3),
          rayCount: 128,
          stokes: stokes([1, 0, 0, 0]),
          direction,
          coneHalfAngle: {
            dtype: 'float64',
            value: 2.5,
            unit: 'deg',
            quantityKind: 'PlaneAngle',
          },
        },
      },
    ],
    boundaryConditions: [
      {
        target: ['experiment.surface.abgBaffle'],
        methodId: 'ray.abg-scatter',
        parameters: {
          scatterFraction: {
            dtype: 'float64',
            value: 0.8,
            unit: '{fraction}',
            quantityKind: 'DimensionlessRatio',
          },
          b: {
            dtype: 'float64',
            value: 0.02,
            unit: '1',
            quantityKind: 'Dimensionless',
          },
          g: {
            dtype: 'float64',
            value: 1.8,
            unit: '1',
            quantityKind: 'Dimensionless',
          },
        },
      },
      {
        target: ['experiment.surface.lambertianBaffle'],
        methodId: 'ray.lambertian-scatter',
        parameters: {
          scatterFraction: {
            dtype: 'float64',
            value: 1,
            unit: '{fraction}',
            quantityKind: 'DimensionlessRatio',
          },
        },
      },
      {
        target: ['experiment.geometry.haze'],
        methodId: 'ray.hg-medium',
        parameters: {
          anisotropy: {
            dtype: 'float64',
            value: 0.65,
            unit: '1',
            quantityKind: 'Dimensionless',
          },
        },
      },
      {
        methodId: 'ray.absorbing-detector',
        target: ['experiment.surface.detector'],
        parameters: {},
      },
    ],
    outputs: [
      {
        key: 'fluenceRate',
        methodId: 'ray.fluence-rate',
        target: ['task.geometry.outputGrid'],
        parameters: { gridShape: [24, 24, 16] },
      },
      {
        key: 'radiantFluxDensity',
        methodId: 'ray.radiant-flux-density',
        target: ['task.geometry.outputGrid'],
        parameters: { gridShape: [24, 24, 16] },
      },
    ],
    exports: [],
  }),
  geometryGroup: { outputGrid: ['output-grid'] },
})

